import{_ as t,o as a,c as r,ae as n}from"./chunks/framework.Dn6zxbF8.js";const h=JSON.parse('{"title":"Live infrastructure","description":"","frontmatter":{"id":"6561361204","title":"Live infrastructure","state":"Approved","created":"2026-10-07T00:00:00.000Z","tags":["directory","devops","terragrunt","terraform","gitops"],"category":"Platform"},"headers":[],"relativePath":"adrs/6561361204/README.md","filePath":"adrs/6561361204/README.md"}'),s={name:"adrs/6561361204/README.md"};function o(i,e,l,c,p,d){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="live-infrastructure" tabindex="-1">Live infrastructure <a class="header-anchor" href="#live-infrastructure" aria-label="Permalink to &quot;Live infrastructure&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> reserves <code>devops/infra/</code> for the live estate. This ADR fixes the layout inside it.</p><p>Building an image or rendering a chart touches nothing live. Terraform units and GitOps manifests do, so the repositories that had settled this keep the live estate under its own subtree with its own code owners, one Terragrunt tree per provider so that a unit for one provider cannot reach another, and reusable modules outside the gate because they reach nothing on their own.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> keep everything that creates, changes or reconciles a live account or cluster under <code>devops/infra/</code>. Nothing else lives there except what this ADR names: its mise configuration and its documentation. A <code>CODEOWNERS</code> entry for that path <strong>MUST</strong> name the owners of the estate.</li><li>You <strong>MAY</strong> make <code>devops/infra/</code> a mise configuration root of its own, so its tasks and secret references resolve only from inside that tree, and the root <code>mise.toml</code> keeps the tool pins.</li></ul><h3 id="terragrunt" tabindex="-1">Terragrunt <a class="header-anchor" href="#terragrunt" aria-label="Permalink to &quot;Terragrunt&quot;">​</a></h3><ul><li>You <strong>MUST</strong> give each provider its own Terragrunt tree under <code>devops/infra/terraform/&lt;provider&gt;/</code>. A unit under one provider <strong>MUST NOT</strong> be able to reach another.</li><li>You <strong>MUST</strong> place <code>root.hcl</code> at the top of each tree that owns its own state and credentials: <code>&lt;provider&gt;/root.hcl</code> for a provider that is one tenant, <code>&lt;provider&gt;/&lt;account&gt;/root.hcl</code> for a provider that isolates by account.</li><li>You <strong>MUST</strong> split a tree by account, project or organisation, and a provider that has regions <strong>MUST</strong> then split by region with <code>_global/</code> for region-free units: <code>&lt;provider&gt;/&lt;account&gt;/{_global,&lt;region&gt;}/&lt;unit&gt;/</code>. The directory <strong>MUST</strong> decide which account and region a run reaches; a credential <strong>MUST NOT</strong>.</li><li>You <strong>MUST</strong> keep lookup tables shared by several provider trees, such as <code>accounts.hcl</code> and <code>generate-versions.hcl</code>, directly under <code>devops/infra/terraform/</code>.</li><li>You <strong>MUST</strong> keep reusable modules and unit templates in <code>devops/terragrunt/catalog/&lt;provider&gt;/{modules,units}/</code>, outside the ownership gate, because they reach nothing live. A unit&#39;s <code>source</code> points at a catalog module; a unit <strong>MAY</strong> carry its own <code>.tf</code> files only when no second consumer exists.</li></ul><h3 id="gitops" tabindex="-1">GitOps <a class="header-anchor" href="#gitops" aria-label="Permalink to &quot;GitOps&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> place what a controller reconciles onto a cluster under <code>devops/infra/gitops/clusters/&lt;cluster&gt;/&lt;kind&gt;/&lt;name&gt;/</code>, one Kustomization per directory.</p></li><li><p>Nothing under <code>terraform/</code> <strong>MUST</strong> read it, and no CI job <strong>MUST</strong> apply it.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>devops</span></span>
<span class="line"><span>├── infra</span></span>
<span class="line"><span>│   ├── mise.toml                          # nested mise config root</span></span>
<span class="line"><span>│   ├── terraform</span></span>
<span class="line"><span>│   │   ├── accounts.hcl                   # shared lookups</span></span>
<span class="line"><span>│   │   ├── generate-versions.hcl</span></span>
<span class="line"><span>│   │   ├── aws</span></span>
<span class="line"><span>│   │   │   └── &lt;account&gt;</span></span>
<span class="line"><span>│   │   │       ├── root.hcl</span></span>
<span class="line"><span>│   │   │       ├── _global/&lt;unit&gt;/terragrunt.hcl</span></span>
<span class="line"><span>│   │   │       └── &lt;region&gt;/&lt;unit&gt;/terragrunt.hcl</span></span>
<span class="line"><span>│   │   └── &lt;provider&gt;</span></span>
<span class="line"><span>│   │       ├── root.hcl</span></span>
<span class="line"><span>│   │       └── &lt;org or project&gt;/&lt;unit&gt;/terragrunt.hcl</span></span>
<span class="line"><span>│   ├── gitops/clusters/&lt;cluster&gt;/applications/&lt;name&gt;/kustomization.yaml</span></span>
<span class="line"><span>│   └── docs/                              # Diátaxis</span></span>
<span class="line"><span>└── terragrunt/catalog/&lt;provider&gt;/{modules,units}/&lt;name&gt;/</span></span></code></pre></div></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="./../2078011537/README.html">ADR#2078011537</a>: Operational assets</li><li><a href="https://terragrunt.gruntwork.io/docs/features/units/" target="_blank" rel="noreferrer">Terragrunt units</a></li><li><a href="https://fluxcd.io/flux/guides/repository-structure/" target="_blank" rel="noreferrer">Flux repository structure</a></li></ul>`,12)])])}const g=t(s,[["render",o]]);export{h as __pageData,g as default};
